    WORD32 sao_blk_wd = ctb_size;
    WORD32 remaining_rows;
    WORD32 remaining_cols;

    remaining_rows = ps_sps->i2_pic_height_in_luma_samples - ((ps_sao_ctxt->i4_ctb_y << log2_ctb_size) + ctb_size - SAO_SHIFT_CTB);
